<?php
namespace App\Services\Marketing;
use App\Models\{MarketingContentTemplate as Template,ManagedSocialAccount};
use Illuminate\Support\Facades\{DB,Http};
use Illuminate\Support\Str;
class MarketingContentTemplates {
 public function query(int $user){return Template::where('merchant_key',app(MarketingPosts::class)->merchant())->where('user_id',$user);}
 public function view(Template $t):array{return ['id'=>$t->id,'archived'=>$t->archived_at!==null,'channel'=>$t->channel,'name'=>$t->name,'language'=>$t->language,'category'=>$t->category,'account_id'=>$t->account_id,'state'=>$t->state,'version'=>$t->version,'provider_code'=>$t->provider_code,'provider_id'=>$t->provider_id,'document'=>$t->document,'updated_at'=>$t->updated_at?->toIso8601String()];}
 public function listing(int $u):array{return $this->query($u)->latest('updated_at')->get()->map(fn($t)=>$this->view($t))->all();}
 public function accounts():array{return ManagedSocialAccount::where('merchant_key',app(MarketingPosts::class)->merchant())->where('platform','whatsapp')->get()->map(fn($a)=>['id'=>$a->id,'name'=>$a->name,'number'=>$a->display_phone_number,'state'=>$a->state])->all();}
 private function account(string $id):ManagedSocialAccount{$a=ManagedSocialAccount::where('merchant_key',app(MarketingPosts::class)->merchant())->where('platform','whatsapp')->find($id);abort_unless($a,422,'Choose an available business number.');return $a;}
 public function save(int $u,array $d,?string $id=null):array{return DB::transaction(function()use($u,$d,$id){$t=$id?$this->query($u)->lockForUpdate()->findOrFail($id):new Template(['merchant_key'=>app(MarketingPosts::class)->merchant(),'user_id'=>$u,'version'=>0]);abort_unless($t->version===$d['version'],409,'This template changed. Reload before saving.');abort_if($t->archived_at,409,'Restore this template before editing.');abort_if($t->exists&&$t->channel!==$d['channel'],422,'Create another template to change channel.');abort_if($t->exists&&$t->state!=='Draft',409,'Create a new draft to preserve the submitted version.');
  $account=null;$examples=$d['examples']??[];$wa=[];
  if($d['channel']==='whatsapp'){
   abort_unless(!empty($d['account_id']),422,'Choose a connected business number.');$account=$this->account($d['account_id']);abort_unless($account->state==='connected'&&$account->app_id===(string)config('services.whatsapp.app_id'),422,'Reconnect this business number before saving its template.');
   $wa=app(WhatsAppTemplateContract::class)->normalize($d);
  }
  foreach($d['assets']??[] as $asset)abort_unless(app(MarketingPosts::class)->asset($u,$asset),422,'Choose media from your existing library.');
  $url=$d['url']??'';if($url!==''){$parts=parse_url($url);abort_unless(filter_var($url,FILTER_VALIDATE_URL)&&($parts['scheme']??'')==='https'&&!isset($parts['user'])&&!isset($parts['pass'])&&!str_contains($url,'{{'),422,'Use a complete HTTPS button destination without credentials or variables.');}
  abort_if(($d['button']??'')!==''&&$url===''||$url!==''&&($d['button']??'')==='',422,'Provide both button text and website destination.');
  $doc=['body'=>$d['body'],'subject'=>$d['subject']??'','footer'=>$d['footer']??'','button'=>$d['button']??'','url'=>$url,'examples'=>$examples,'format'=>$d['format']??'image','assets'=>$d['assets']??[]]+$wa;
  $t->fill(['channel'=>$d['channel'],'account_id'=>$account?->id,'waba_id'=>$account?->waba_id,'name'=>$d['name'],'language'=>$d['language'],'category'=>$d['channel']==='whatsapp'?($wa['category']??'MARKETING'):null,'document'=>$doc,'state'=>'Draft','version'=>$t->version+1]);$t->save();return $this->view($t);
 });}
 private function provider(ManagedSocialAccount $a,string $method,string $path,array $payload=[]):array {
  try{$request=Http::withToken($a->access_token)->acceptJson()->withoutRedirecting()->connectTimeout(5)->timeout(20);$url='https://graph.facebook.com/'.config('services.whatsapp.graph_version','v25.0').'/'.$path;$r=$method==='GET'?$request->get($url,$payload):$request->post($url,$payload);$body=$r->json();abort_unless($r->successful()&&is_array($body)&&!isset($body['error']),409,'The template status could not be confirmed. Existing content is retained.');return $body;}catch(\Illuminate\Http\Client\ConnectionException){abort(409,'The request result is unknown. Check status before submitting again.');}
 }
 public function submit(int $u,string $id,int $version):array {
  abort_unless(config('marketing.whatsapp_template_submission_enabled',false),409,'Template submission will be available after the WhatsApp connection is verified. Your draft is saved.');
  $t=DB::transaction(function()use($u,$id,$version){$t=$this->query($u)->lockForUpdate()->findOrFail($id);abort_unless($t->channel==='whatsapp'&&!$t->archived_at&&$t->state==='Draft'&&$t->version===$version,409,'Reload this template before submitting.');$a=$this->account($t->account_id);abort_unless($a->state==='connected'&&$a->waba_id===$t->waba_id&&$a->app_id===(string)config('services.whatsapp.app_id'),409,'Reconnect the original business number.');$contract=app(WhatsAppTemplateContract::class);$normalized=$contract->normalize(['name'=>$t->name,'body'=>$t->document['body'],'category'=>$t->category]+$t->document,true);$t->update(['document'=>array_merge($t->document,$normalized),'state'=>'Submitting','version'=>$t->version+1]);return $t;});
  $doc=$t->document;$components=app(WhatsAppTemplateContract::class)->components($doc);
  try{$result=$this->provider($this->account($t->account_id),'POST',$t->waba_id.'/message_templates',['name'=>$doc['meta_name']??$t->name,'language'=>$t->language,'category'=>$t->category,'components'=>$components]);$providerId=$result['id']??null;abort_unless(is_string($providerId)&&ctype_digit($providerId),409,'Submission needs a status check.');$t->update(['provider_id'=>$providerId,'state'=>'Pending approval','version'=>$t->version+1]);}
  catch(\Throwable $e){$t->update(['state'=>'Status check required','provider_code'=>'submission_unconfirmed','version'=>$t->version+1]);abort(409,'The submission result could not be confirmed. Check status before trying again.');}return $this->view($t->fresh());
 }
 public function sync(int $u,string $id,int $version):array {
  $t=$this->query($u)->findOrFail($id);abort_unless($t->channel==='whatsapp'&&$t->version===$version,409,'Reload this template before checking status.');$a=$this->account($t->account_id);abort_unless($a->state==='connected'&&$a->waba_id===$t->waba_id&&$a->app_id===(string)config('services.whatsapp.app_id'),409,'Reconnect the original business number.');
  $body=$this->provider($a,'GET',$t->waba_id.'/message_templates',['name'=>$t->document['meta_name']??$t->name,'fields'=>'id,name,status,language,category,rejected_reason,components','limit'=>100]);$remote=collect($body['data']??[])->first(fn($x)=>is_array($x)&&($x['name']??null)===($t->document['meta_name']??$t->name)&&($x['language']??null)===$t->language);
  abort_unless($remote,409,'No matching template was returned. Existing content is retained.');
  $state=match($remote['status']??''){'APPROVED'=>'Approved','PENDING'=>'Pending approval','REJECTED'=>'Changes needed','PAUSED'=>'Paused','DISABLED'=>'Disabled',default=>'Status check required'};
  // An approval is only reusable if the remotely approved content matches this revision.
  $cleanRemote=[];foreach($remote['components']??[] as $c){unset($c['example']);if(($c['type']??'')==='BUTTONS')foreach($c['buttons'] as &$b){unset($b['example']);}unset($b);$cleanRemote[]=$c;}
  $expected=app(WhatsAppTemplateContract::class)->components($t->document,false);$providerId=$remote['id']??null;$match=is_string($providerId)&&ctype_digit($providerId)&&($remote['category']??null)===$t->category&&$this->canonical($cleanRemote)===$this->canonical($expected);if($state==='Approved'&&!$match)$state='Status check required';

  $changed=$this->query($u)->whereKey($id)->where('version',$version)->update(['provider_id'=>(string)($remote['id']??''),'state'=>$state,'provider_code'=>$state==='Changes needed'?'provider_rejected':null,'document'=>json_encode(array_merge($t->document,['last_synced_at'=>now()->toIso8601String()]),JSON_THROW_ON_ERROR),'version'=>$version+1,'updated_at'=>now()]);abort_unless($changed,409,'This template changed. Reload to see its status.');return $this->view($t->fresh());
 }
 private function canonical(array $value):string{$sort=function($v)use(&$sort){if(!is_array($v))return $v;if(!array_is_list($v))ksort($v);foreach($v as $k=>$x)$v[$k]=$sort($x);return $v;};return json_encode($sort($value),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}
 public function duplicate(int $u,string $id,?int $version=null):array {$t=$this->query($u)->findOrFail($id);abort_if($version!==null&&$t->version!==$version,409,'This template changed. Reload before duplicating.');$copy=$t->replicate(['provider_id','provider_code']);$copy->forceFill(['archived_at'=>null,'id'=>(string)Str::uuid(),'name'=>mb_substr($t->name,0,104).'_'.strtolower(Str::random(6)),'state'=>'Draft','version'=>1]);$doc=$copy->document;unset($doc['last_synced_at']);if(isset($doc['meta_name']))$doc['meta_name']=mb_substr($doc['meta_name'],0,104).'_'.strtolower(Str::random(6));$copy->document=$doc;$copy->save();return $this->view($copy);}
 public function archive(int $u,string $id,int $version,bool $restore=false):array {return DB::transaction(function()use($u,$id,$version,$restore){$t=$this->query($u)->lockForUpdate()->findOrFail($id);abort_unless($t->version===$version,409,'This template changed. Reload before updating it.');abort_if(in_array($t->state,['Submitting'],true),409,'Wait for the submission result before archiving.');$t->update(['archived_at'=>$restore?null:now(),'version'=>$t->version+1]);return $this->view($t);});}
 public function usePost(int $u,string $id):array {$t=$this->query($u)->findOrFail($id);abort_unless($t->channel==='post'&&!$t->archived_at,422,'Restore this template before using it.');$d=$t->document;return app(MarketingPosts::class)->write($u,'draft',['id'=>(string)Str::uuid(),'version'=>0,'title'=>$t->name,'copy'=>$d['body'],'targets'=>[],'copies'=>[],'assets'=>$d['assets'],'asset'=>$d['assets'][0]??null,'format'=>$d['format'],'type'=>$d['format']==='video'?'Reel':'Post','tz'=>config('app.timezone','UTC')]);}
}
